30	type nativeProviderResolution struct {
31		Provider agentcore.Provider
32		Name     string
33		Entry    ServiceProviderEntry
34	}
35	
36	func (s *service) resolveConfiguredNativeProvider(req ServiceExecuteRequest) nativeProviderResolution {
37		sc := s.opts.ServiceConfig
38		if sc == nil {
39			return nativeProviderResolution{}
40		}
41		name, entry, ok := selectConfiguredNativeProvider(sc, req)
42		if !ok {
43			return nativeProviderResolution{}
44		}
45		if req.Model != "" {
46			entry.Model = req.Model
47		}
48		provider := s.buildNativeProvider(name, entry)
49		if provider == nil {
50			return nativeProviderResolution{Name: name, Entry: entry}
51		}
52		return nativeProviderResolution{Provider: provider, Name: name, Entry: entry}
53	}
54	
55	func selectConfiguredNativeProvider(sc ServiceConfig, req ServiceExecuteRequest) (string, ServiceProviderEntry, bool) {
56		if req.Provider != "" {
57			if entry, ok := sc.Provider(req.Provider); ok {
58				return req.Provider, entry, true
59			}
60			if name, entry, ok := selectConfiguredEndpointProvider(sc, req.Provider); ok {
61				return name, entry, true
62			}
63		}
64	
65		wantedType := requestedNativeProviderType(req)
66		if wantedType != "" {
67			if name := sc.DefaultProviderName(); name != "" {
68				if entry, ok := sc.Provider(name); ok && normalizeServiceProviderType(entry.Type) == wantedType {
69					return name, entry, true
70				}
71			}
72			for _, name := range sc.ProviderNames() {
73				entry, ok := sc.Provider(name)
74				if ok && normalizeServiceProviderType(entry.Type) == wantedType {
75					return name, entry, true
76				}
77			}
78		}
79	
80		if req.Provider == "" && wantedType == "" {
81			name := sc.DefaultProviderName()
82			if name == "" {
83				return "", ServiceProviderEntry{}, false
84			}
85			entry, ok := sc.Provider(name)
86			return name, entry, ok
87		}
88	
89		return "", ServiceProviderEntry{}, false
90	}
91	
92	func selectConfiguredEndpointProvider(sc ServiceConfig, ref string) (string, ServiceProviderEntry, bool) {
93		providerName, endpointName, ok := splitEndpointProviderRef(ref)
94		if !ok {
95			return "", ServiceProviderEntry{}, false
96		}
97		entry, ok := sc.Provider(providerName)
98		if !ok {
99			return "", ServiceProviderEntry{}, false
100		}
101		for _, endpoint := range modelDiscoveryEndpoints(entry) {
102			if endpoint.Name != endpointName {
103				continue
104			}
105			entry.BaseURL = endpoint.BaseURL
106			entry.ServerInstance = endpoint.ServerInstance
107			entry.Endpoints = []ServiceProviderEndpoint{{Name: endpoint.Name, BaseURL: endpoint.BaseURL}}
108			return ref, entry, true
109		}
110		return "", ServiceProviderEntry{}, false
111	}
112	
113	func endpointProviderRef(providerName, endpointName string) string {
114		if endpointName == "" {
115			return providerName
116		}
117		return providerName + "@" + endpointName
118	}
119	
120	func splitEndpointProviderRef(ref string) (string, string, bool) {
121		providerName, endpointName, ok := strings.Cut(ref, "@")
122		if !ok || providerName == "" || endpointName == "" {
123			return "", "", false
124		}
125		return providerName, endpointName, true
126	}
127	
128	func requestedNativeProviderType(req ServiceExecuteRequest) string {
129		if req.Provider != "" {
130			return normalizeServiceProviderType(req.Provider)
131		}
132		switch req.Harness {
133		case "", "fiz":
134			return ""
135		default:
136			return normalizeServiceProviderType(req.Harness)
137		}
138	}
139	
140	func (s *service) nativeProviderNotConfiguredError(req ServiceExecuteRequest, decision RouteDecision) string {
141		wantedType := requestedNativeProviderType(req)
142		if wantedType == "" {
143			errMsg := "orphan model: " + decision.Model
144			if decision.Model == "" {
145				errMsg = "no provider configured for native harness"
146			}
147			return errMsg
148		}
149		available := s.availableProviderTypes()
150		harness := decision.Harness
151		if harness == "" {
152			harness = "fiz"
153		}
154		return fmt.Sprintf("harness %q: no configured provider matches type %q (available: %s)", harness, wantedType, available)
155	}
156	
157	func (s *service) availableProviderTypes() string {
158		sc := s.opts.ServiceConfig
159		if sc == nil {
160			return "[]"
161		}
162		var parts []string
163		for _, name := range sc.ProviderNames() {
164			entry, ok := sc.Provider(name)
165			if !ok {
166				continue
167			}
168			parts = append(parts, fmt.Sprintf("%s (%s)", name, normalizeServiceProviderType(entry.Type)))
169		}
170		if len(parts) == 0 {
171			return "[]"
172		}
173		return "[" + strings.Join(parts, ", ") + "]"
174	}
