176	// buildNativeProvider is the service-time factory. Per agent-8e4eb44c
177	// the per-type switch is gone; both this and internal/config's
178	// BuildProvider go through registry.Lookup. Adding a new provider type
179	// is one Register() call in the new package; no edits to this file
180	// or internal/config/config.go's factory.
181	func (s *service) buildNativeProvider(name string, entry ServiceProviderEntry) agentcore.Provider {
182		if entry.ConfigError != "" {
183			return nil
184		}
185		typ := normalizeServiceProviderType(entry.Type)
186		if d, ok := registry.Lookup(typ); ok {
187			return d.Factory(registry.Inputs{
188				ProviderName:        name,
189				BaseURL:             entry.BaseURL,
190				APIKey:              entry.APIKey,
191				Model:               entry.Model,
192				ModelReasoningWire:  nativeModelReasoningWireMap(),
193				QuotaSignalObserver: s.quotaSignalObserver(name),
194			})
195		}
196		return nil
197	}
198	
199	// quotaSignalObserver returns a callback that updates the provider quota
200	// state machine when a parsed rate-limit signal indicates the provider's
201	// subscription/daily cap has been hit (or imminently will be). Returns nil
202	// when the service has no quota store, which makes the provider middleware
203	// a no-op.
204	func (s *service) quotaSignalObserver(providerName string) func(quotaheaders.Signal) {
205		if s == nil || s.providerQuota == nil || providerName == "" {
206			return nil
207		}
208		store := s.providerQuota
209		return func(signal quotaheaders.Signal) {
210			now := time.Now()
211			exhausted, retryAt := signal.IsExhausted(now)
212			if !exhausted {
213				return
214			}
215			if retryAt.IsZero() {
216				// Provider said "exhausted" but gave us no reset window. Fall
217				// back to a short cooldown so we don't peg the provider in the
218				// excluded set forever; the next response will refresh us.
219				retryAt = now.Add(time.Minute)
220			}
221			store.MarkQuotaExhausted(providerName, retryAt)
222		}
223	}
224	
225	// nativeModelReasoningWireMap returns the catalog reasoning_wire map for use
226	// by the native (service-side) provider builder. Models without an explicit
227	// reasoning_wire are omitted; the provider treats absence as the "provider"
228	// default.
229	func nativeModelReasoningWireMap() map[string]string {
230		cat, err := modelcatalog.Default()
231		if err != nil {
232			return nil
233		}
234		all := cat.AllModels()
235		if len(all) == 0 {
236			return nil
237		}
238		out := make(map[string]string, len(all))
239		for id, entry := range all {
240			if entry.ReasoningWire != "" {
241				out[id] = entry.ReasoningWire
242			}
243		}
244		return out
245	}
