671	// buildRoutingInputs assembles routing.Inputs from the service's registry
672	// and snapshot-derived provider inventory. The public routing engine stays
673	// unchanged; only the source of provider/model candidates changes.
674	func (s *service) buildRoutingInputs(ctx context.Context) routing.Inputs {
675		// Route hot paths are cache-first: stale or missing provider facts may
676		// request a coordinated background refresh, but routing never blocks on
677		// local provider probes or model discovery before scoring candidates.
678		inputs, _ := s.buildRoutingInputsWithCatalog(ctx, serviceRoutingCatalog(), modelsnapshot.RefreshBackground)
679		return inputs
680	}
681	
682	func (s *service) buildRoutingInputsWithCatalog(ctx context.Context, cat *modelcatalog.Catalog, refresh modelsnapshot.RefreshMode) (routing.Inputs, modelsnapshot.ModelSnapshot) {
683		if refresh == modelsnapshot.RefreshBackground {
684			s.requestLocalHealthRefreshForRouting(ctx)
685		}
686		statuses := s.registry.Discover()
687		statusByName := make(map[string]harnesses.HarnessStatus, len(statuses))
688		for _, st := range statuses {
689			statusByName[st.Name] = st
690		}
691		now := time.Now().UTC()
692		var snapshot modelsnapshot.ModelSnapshot
693		if s.opts.ServiceConfig != nil {
694			if cacheRoot, err := serviceSnapshotCacheRoot(); err == nil {
695				snapshot, _ = assembleModelSnapshotFromServiceConfigWithOptions(
696					ctx,
697					s.opts.ServiceConfig,
698					cat,
699					cacheRoot,
700					modelsnapshot.AssembleOptions{Refresh: refresh},
701				)
702			}
703		}
704	
705		var entries []routing.HarnessEntry
706		for _, name := range s.registry.Names() {
707			cfg, ok := s.registry.Get(name)
708			if !ok {
709				continue
710			}
711			st := statusByName[name]
712			entry := routingHarnessEntryFromMetadata(name, cfg, st)
713			if name == "fiz" && s.opts.ServiceConfig == nil {
714				entry.AutoRoutingEligible = false
715			}
716	
717			if qs, ok := subscriptionQuotaForHarness(name, time.Now()); ok {
718				entry.QuotaOK = qs.OK
719				entry.QuotaStale = qs.Present && !qs.Fresh
720				entry.SubscriptionOK = qs.OK
721				entry.QuotaPercentUsed = qs.PercentUsed
722				entry.QuotaTrend = qs.Trend
723				entry.QuotaReason = qs.Reason
724			}
725	
726			// Native "fiz" harness: enumerate snapshot-derived provider rows.
727			if name == "fiz" && s.opts.ServiceConfig != nil {
728				entry.Providers = s.snapshotProviderEntries(ctx, cat, snapshot)
729				// Tool support for the agent harness is per-(provider, model);
730				// the harness-level baseline is whether ANY provider supports
731				// tools. Engine OR-combines harness and provider SupportsTools
732				// so this lets a per-model no_tools catalog flag actually fire
733				// the RequiresTools gate when every provider's resolved model
734				// is no-tools.
735				if len(entry.Providers) > 0 {
736					entry.SupportsTools = anyProviderSupportsTools(entry.Providers)
737				} else {
738					entry.Available = false
739				}
740			}
741			// Subscription harnesses (claude/codex/gemini) expose multiple tiers
742			// under one auth. Use the catalog surface to enumerate the active
743			// concrete tier IDs so the engine emits one candidate per tier and
744			// the cost-aware scorer can pick the cheapest viable tier instead of
745			// silently collapsing to DefaultModel.
746			if entry.IsSubscription {
747				if tiers := catalogTierModelsForHarnessSurface(cat, entry.Surface); len(tiers) > 0 {
748					entry.AutoRoutingModels = tiers
749					entry.SupportedModels = appendUniqueModelIDs(entry.SupportedModels, tiers...)
750				}
751			}
752			s.applySubscriptionRoutingCost(&entry, cat)
753			entries = append(entries, entry)
754		}
755		successRate, latencyMS := s.routeMetricSignals(now, s.routeAttemptTTL())
756	
757		// FEAT-004 AC-28: known-down endpoints are dispatchability failures.
758		// Surface provider-level dial failures from cached snapshot discovery
759		// sources via ProviderUnreachable so the routing engine hard-gates known
760		// failures before any dispatch attempt.
761		healthCooldownTTL := s.routeAttemptTTL()
762		providerUnreachable := providerCooldownsFromSnapshotErrors(snapshot, s.opts.ServiceConfig, now, healthCooldownTTL)
763	
764		// Proactive probe failures feed ProbeUnreachable (separate from
765		// ProviderUnreachable which is populated from dial failures). TTL is
766		// HealthSignalTTL (default 10 min) — longer than the cooldown window.
767		var probeUnreachable map[string]time.Time
768		var probeUnknown map[string]time.Time
769		if s.providerProbe != nil {
770			probeUnreachable = s.probeUnreachableProviders(now)
771			probeUnknown = s.probeUnknownProviders(now)
772		}
773	
774		// Credential gate (synchronous, network-free): providers that need an API
775		// key but lack one are filtered out before any HTTP I/O can occur, so the
776		// operator sees the missing-credential root cause instead of a 401 from
777		// the dispatch path.
778		providerCredentialMissing := providerCredentialMissingMap(s.opts.ServiceConfig)
779	
780		// Credit-balance gate plus failure-mode classification: the credit probe
781		// produces credit_exhausted, credential_invalid, and provider_unreachable
782		// evidence in one cache pass. The probe is cached per-provider with a TTL
783		// so back-to-back Execute calls within the window share one
784		// /api/v1/credits round-trip.
785		probeMaps := s.openrouterProbeMaps(ctx, now)
786	
787		return routing.Inputs{
788			Harnesses:                    entries,
789			ProviderSuccessRate:          successRate,
790			ObservedLatencyMS:            latencyMS,
791			ProviderQuotaExhaustedUntil:  s.providerQuotaExhaustedUntil(now),
792			ProviderUnreachable:          providerUnreachable,
793			ProbeUnreachable:             probeUnreachable,
794			ProbeUnknown:                 probeUnknown,
795			ProviderCredentialMissing:    providerCredentialMissing,
796			ProviderCreditExhausted:      probeMaps.CreditExhausted,
797			ProviderCredentialInvalid:    probeMaps.CredentialInvalid,
798			ProviderProbeUnreachable:     probeMaps.ProviderUnreachable,
799			CooldownDuration:             healthCooldownTTL,
800			Now:                          now,
801			ModelEligibility:             serviceRoutingModelEligibility(entries, cat),
802			ReasoningResolver:            serviceRoutingReasoningResolver(cat),
803			EndpointLoadResolver:         s.routeEndpointLoadsResolver(now),
804			StickyServerInstanceResolver: s.routeStickyServerInstanceResolver(now),
805		}, snapshot
806	}
807	
808	// providerCredentialMissingMap inspects each configured provider that
809	// authenticates with an API key and reports the ones whose credential is
810	// missing or obviously malformed. The map's value is the credential location
811	// (env var / config field) that was inspected, so operator-facing evidence
812	// can show WHICH key location was checked.
813	//
814	// The check is synchronous and side-effect free: it never issues an HTTP
815	// request. Server-side credential rejection (401 after dispatch) is a
816	// separate failure mode reserved for a future filter reason.
817	func providerCredentialMissingMap(cfg ServiceConfigSource) map[string]string {
818		if cfg == nil {
819			return nil
820		}
821		names := cfg.ProviderNames()
822		if len(names) == 0 {
823			return nil
824		}
825		provider, ok := cfg.(interface {
826			Provider(name string) (ServiceProviderEntry, bool)
827		})
828		if !ok {
829			return nil
830		}
831		out := make(map[string]string)
832		for _, name := range names {
833			pcfg, ok := provider.Provider(name)
834			if !ok {
835				continue
836			}
837			location, missing := credentialMissingForProvider(name, pcfg)
838			if missing {
839				out[name] = location
840			}
841		}
842		if len(out) == 0 {
843			return nil
844		}
845		return out
846	}
847	
848	// credentialMissingForProvider returns (location, true) when the named
849	// provider needs an API key but the configured value is empty or obviously
850	// malformed. location names the field the operator should set.
851	//
852	// The malformed heuristic is intentionally narrow: it catches blatant typos
853	// (wrong prefix or length far below any plausible key) without ever calling
854	// the provider. Server-side validity is out of scope here — the rejection
855	// path will materialize the credential_invalid reason separately.
856	func credentialMissingForProvider(name string, pcfg ServiceProviderEntry) (string, bool) {
857		if normalizeServiceProviderType(pcfg.Type) != "openrouter" {
858			return "", false
859		}
860		key := strings.TrimSpace(pcfg.APIKey)
861		location := fmt.Sprintf("providers.%s.api_key (or OPENROUTER_API_KEY env)", name)
862		if key == "" {
863			return location, true
864		}
865		// Unexpanded env placeholder: config load preserves the literal
866		// "${VAR}" verbatim when VAR is unset (internal/config/config_test.go
867		// TestLoad_EnvExpansion_Unset). This catches both the bare placeholder
868		// and partial substitutions like "sk-or-${KEY_SUFFIX}" that would
869		// otherwise sneak past the prefix/length heuristic.
870		if strings.Contains(key, "${") {
871			return location, true
872		}
873		if !openrouterAPIKeyWellFormed(key) {
874			return location, true
875		}
876		return "", false
877	}
878	
879	// openrouterAPIKeyWellFormed reports whether s plausibly resembles a real
880	// OpenRouter API key. The heuristic checks the well-known "sk-or-" prefix and
881	// a minimum length floor that excludes obvious typos. It does NOT confirm
882	// server-side validity.
883	func openrouterAPIKeyWellFormed(s string) bool {
884		const (
885			expectedPrefix  = "sk-or-"
886			minPlausibleLen = 20
887		)
888		if !strings.HasPrefix(s, expectedPrefix) {
889			return false
890		}
891		if len(s) < minPlausibleLen {
892			return false
893		}
894		return true
895	}
