938	// ServiceConfigSource is the minimal interface providerCooldownsFromSnapshotErrors
939	// needs from the service config. The real service.opts.ServiceConfig satisfies
940	// it, and tests can pass a stub.
941	type ServiceConfigSource interface {
942		ProviderNames() []string
943	}
