1216	// startQuotaRecoveryProbeLoop spawns the goroutine that periodically probes
1217	// quota_exhausted providers and either restores them to available or extends
1218	// their retry_after with bounded backoff. The goroutine is tied to
1219	// QuotaRefreshContext (or context.Background()) so server callers can cancel
1220	// it on shutdown.
1221	func (s *service) startQuotaRecoveryProbeLoop() {
1222		if s == nil || s.providerQuota == nil {
1223			return
1224		}
1225		ctx := s.opts.QuotaRefreshContext
1226		if ctx == nil {
1227			ctx = context.Background()
1228		}
1229		probe := s.quotaRecoveryProber()
1230		if probe == nil {
1231			return
1232		}
1233		go runQuotaRecoveryProbeLoop(ctx, s.providerQuota, probe, defaultQuotaRecoveryFallbackInterval, nil, nil)
1234	}
1235	
1236	// quotaRecoveryProber returns the QuotaRecoveryProber used by the recovery
1237	// loop. It looks up the provider entry in ServiceConfig and reuses the same
1238	// probeProviderStatus the HealthCheck endpoint uses; a "connected" status
1239	// counts as recovery, anything else is reported as a probe failure so the
1240	// retry_after gets extended with backoff.
1241	func (s *service) quotaRecoveryProber() QuotaRecoveryProber {
1242		sc := s.opts.ServiceConfig
1243		if sc == nil {
1244			return nil
1245		}
1246		return func(ctx context.Context, name string) error {
1247			entry, ok := sc.Provider(name)
1248			if !ok {
1249				return fmt.Errorf("provider %q not found", name)
1250			}
1251			probeCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
1252			defer cancel()
1253			probe := probeProviderStatus(probeCtx, entry, time.Now().UTC())
1254			if probe.status == "connected" {
1255				return nil
1256			}
1257			if probe.detail != "" {
1258				return fmt.Errorf("%s", probe.detail)
1259			}
1260			return fmt.Errorf("%s", probe.status)
1261		}
1262	}
