1543	// providerSupportsTools returns whether the provider should be advertised as
1544	// supporting tools to the routing engine. Defaults to true; only flips to
1545	// false when the catalog explicitly marks every relevant model (the
1546	// DefaultModel and any DiscoveredIDs) with no_tools=true.
1547	func providerSupportsTools(cat *modelcatalog.Catalog, defaultModel string, discoveredIDs []string) bool {
1548		if cat == nil {
1549			return true
1550		}
1551		checked := false
1552		if defaultModel != "" {
1553			if cat.SupportsToolsForModel(defaultModel) {
1554				return true
1555			}
1556			checked = true
1557		}
1558		for _, id := range discoveredIDs {
1559			if id == "" {
1560				continue
1561			}
1562			if cat.SupportsToolsForModel(id) {
1563				return true
1564			}
1565			checked = true
1566		}
1567		if !checked {
