1762	func (s *service) subscriptionCostCurve() SubscriptionCostCurve {
1763		if s.opts.SubscriptionCostCurve == nil {
1764			return defaultSubscriptionCostCurve()
1765		}
1766		curve := *s.opts.SubscriptionCostCurve
1767		def := defaultSubscriptionCostCurve()
1768		if curve.FreeUntilPercent == 0 {
1769			curve.FreeUntilPercent = def.FreeUntilPercent
1770		}
1771		if curve.LowUntilPercent == 0 {
1772			curve.LowUntilPercent = def.LowUntilPercent
1773		}
1774		if curve.MediumUntilPercent == 0 {
1775			curve.MediumUntilPercent = def.MediumUntilPercent
1776		}
1777		if curve.LowMultiplier == 0 {
1778			curve.LowMultiplier = def.LowMultiplier
1779		}
1780		if curve.MediumMultiplier == 0 {
1781			curve.MediumMultiplier = def.MediumMultiplier
1782		}
1783		if curve.HighMultiplier == 0 {
1784			curve.HighMultiplier = def.HighMultiplier
1785		}
1786		return curve
1787	}
