func TestDefaultProviderFailsOverWhenUnreachable(t *testing.T) {
	svc := publicRouteTraceService(&fakeServiceConfig{
		providers: map[string]ServiceProviderEntry{
			"lmstudio": {Type: "test", BaseURL: "http://127.0.0.1:9999/v1", ServerInstance: "127.0.0.1:9999", Model: "model-a"},
		},
		names:       []string{"lmstudio"},
		defaultName: "lmstudio",
	})
	in := routing.Inputs{
		Harnesses: []routing.HarnessEntry{
			{
				Name:                  "fiz",
				Surface:               "embedded-openai",
				CostClass:             "local",
				IsLocal:               true,
				AutoRoutingEligible:   true,
				Available:             true,
				SupportsTools:         true,
				Providers: []routing.ProviderEntry{
					{
						Name:           "lmstudio",
						DefaultModel:   "model-a",
						DiscoveredIDs:  []string{"model-a"},
						DiscoveryAttempted: true,
					},
				},
			},
			{
				Name:                "claude",
				Surface:             "embedded-anthropic",
				CostClass:           "expensive",
				IsSubscription:      true,
				AutoRoutingEligible: true,
				Available:           true,
				DefaultModel:        "claude-3-5-sonnet-20241022",
				SupportedModels:     []string{"claude-3-5-sonnet-20241022"},
				SupportsTools:       true,
			},
		},
		ProviderUnreachable: map[string]time.Time{
			"lmstudio": time.Now(),
		},
		CooldownDuration: 1 * time.Minute,
		Now:              time.Now(),
	}
	dec, err := routing.Resolve(routing.Request{}, in)
	if err != nil {
		t.Fatalf("Resolve: %v", err)
	}
	if dec == nil {
		t.Fatal("Resolve returned nil decision")
	}
	if dec.Harness != "claude" {
		t.Fatalf("decision harness=%q, want claude (fallback from unreachable lmstudio)", dec.Harness)
	}
}

